result = Customers.WHERE(
    COUNT(transactions_made) >= 5
).CALCULATE(
    customer_name=name,
    success_rate=100.0 * COUNT(transactions_made.WHERE(LOWER(status) == LOWER('success'))) / COUNT(transactions_made)
).ORDER_BY(success_rate.ASC())

result = Broker.CALCULATE(
    num_customers = COUNT(
        Customers.WHERE(
            ENDSWITH(email, '.com') & 
            HAS(
                transactions_made.WHERE(
                    CONTAINS(ticker.symbol, 'AMZN') |
                    CONTAINS(ticker.symbol, 'AAPL') |
                    CONTAINS(ticker.symbol, 'GOOGL') |
                    CONTAINS(ticker.symbol, 'META') |
                    CONTAINS(ticker.symbol, 'NFLX')
                )
            ) == 1
        )
    )
)

tac_by_country = Customers.WHERE(
    (LOWER(status) == 'active') & (join_date >= '2023-01-01')
).PARTITION(
    name='country_groups', by=(country)
).CALCULATE(
    country=country,
    tac_count=COUNT(Customers)
)

customer_signups_and_transactions = GRAPH.CALCULATE(
    start_of_current_month=DATETIME('now', 'start of month'),
    start_of_period=DATETIME('now', 'start of month', '-6 months')
).Customers.WHERE(
    (join_date >= start_of_period) & (join_date < start_of_current_month)
).CALCULATE(
    signup_month=JOIN_STRINGS("-", YEAR(join_date), LPAD(MONTH(join_date), 2, "0"))
).PARTITION(name="monthly_signups", by=(signup_month)).CALCULATE(
    month=signup_month,
    PMCS=COUNT(Customers),
    PMAT=AVG(Customers.transactions_made.amount)
)

acp_by_type = DailyPrices.WHERE(
    DATEDIFF("days", date, DATETIME('now')) <= 6
).CALCULATE(
    type_of_ticker=ticker.ticker_type
).PARTITION(
    name="type_groups", by=(type_of_ticker,)
).CALCULATE(
    ticker_type=type_of_ticker,
    average_closing_price=AVG(DailyPrices.close)
)

result = Broker.CALCULATE(
    num_customers=COUNT(
        Customers.WHERE(
            (STARTSWITH(LOWER(name), 'j') | ENDSWITH(LOWER(name), 'ez')) &
            ENDSWITH(LOWER(state), 'a')
        )
    )
)

result = Broker.CALCULATE(
    customer_count=COUNT(
        Customers.WHERE(
            (STARTSWITH(LOWER(name), 'j') | ENDSWITH(LOWER(name), 'ez')) &
            ENDSWITH(LOWER(state), 'a')
        )
    )
)

price_change_by_stock = DailyPrices.WHERE(
    (date >= '2023-04-01') & (date <= '2023-04-04')
).CALCULATE(
    ticker_symbol=ticker.symbol
).PARTITION(
    name="stocks", by=(ticker_symbol,)
).CALCULATE(
    ticker_symbol=ticker_symbol,
    price_change=MAX(DailyPrices.high) - MIN(DailyPrices.low)
)

top_stocks_by_price_change = price_change_by_stock.TOP_K(3, by=price_change.DESC())

result = Customers.WHERE(
    HAS(transactions_made.WHERE(LOWER(transaction_type) == LOWER('buy'))) == 1
).CALCULATE(
    customer_id=_id
)

distinct_customer_ids = Transactions.WHERE(LOWER(transaction_type) == 'buy').PARTITION(
    name="distinct_customers", 
    by=(customer_id)
).CALCULATE(
    customer_id
)

result = DailyPrices.WHERE(
    date >= "2023-04-01"
).PARTITION(
    name="tickers", 
    by=ticker_id
).CALCULATE(
    ticker_id=ticker_id
)

distinct_ticker_ids = DailyPrices.WHERE(date >= '2023-04-01').PARTITION(name="distinct_tickers", by=ticker_id).CALCULATE(
    ticker_id=ticker_id
)

result = Tickers.WHERE(
    HASNOT(historical_prices) == 1
).CALCULATE(
    ticker_id=_id,
    symbol=symbol
)

result = Transactions.WHERE(
    DATEDIFF("days", date_time, 'now') <= 30
).CALCULATE(
    country_name=customer.country
).PARTITION(
    name="countries", by=(country_name)
).CALCULATE(
    country=country_name,
    num_transactions=COUNT(Transactions),
    total_transaction_amount=SUM(Transactions.amount)
).TOP_K(5, by=total_transaction_amount.DESC())

result = Tickers.WHERE(symbol == 'VTI').historical_prices.WHERE(
    DATEDIFF("days", date, DATETIME('now')) <= 7
).CALCULATE(
    lowest_close_price=MIN(DailyPrices.close)
)

vti_prices_last_7_days = DailyPrices.WHERE(
    (LOWER(ticker.symbol) == 'vti') & (DATEDIFF("days", date, 'now') <= 7)
)
result = GRAPH.CALCULATE(
    lowest_close_price=MIN(vti_prices_last_7_days.close)
)

result = Broker.CALCULATE(
    num_transactions=COUNT(
        Customers.WHERE(
            DATEDIFF("days", join_date, DATETIME("now")) <= 70
        ).transactions_made
    )
)

result = Customers.WHERE(
    HAS(transactions_made) == 1
).CALCULATE(
    customer_id=_id,
    days_to_first_transaction=DATEDIFF("seconds", join_date, MIN(transactions_made.date_time)) / 86400
)

result = Customers.CALCULATE(
    customer_id=_id,
    customer_name=name,
    num_sell_transactions=COUNT(
        transactions_made.WHERE(
            (DATE(date_time) == "2023-04-01") & 
            (LOWER(transaction_type) == "sell")
        )
    )
).TOP_K(1, by=num_sell_transactions.DESC())

toyota_sales_last_30_days = Cars.WHERE(
    LOWER(make) == LOWER('Toyota')
).sale_records.WHERE(
    DATEDIFF("days", sale_date, DATETIME('now')) <= 30
)

result = Dealership.CALCULATE(
    number_of_sales=COUNT(toyota_sales_last_30_days),
    total_revenue=SUM(toyota_sales_last_30_days.sale_price)
)

result = Sales.WHERE(
    (YEAR(sale_date) == 2023) & 
    (ISIN(MONTH(sale_date), (1, 2, 3)))
).CALCULATE(
    asp_q1_2023 = AVG(Sales.sale_price)
)

average_sale_price_q1_2023 = Dealership.CALCULATE(
    asp_q1_2023=AVG(Sales.WHERE((YEAR(sale_date) == 2023) & (MONTH(sale_date) <= 3)).sale_price)
)

result = Dealership.CALCULATE(
    avg_days_between_sale_and_payment = ROUND(
        AVG(
            Sales.WHERE(HAS(payment) == 1).payment.CALCULATE(
                days_diff = DATEDIFF("days", sale_record.sale_date, payment_date)
            ).days_diff
        ), 
        2
    )
)

avg_payment_time = Sales.WHERE(HAS(payment) == 1).CALCULATE(
    sale_id=_id,
    avg_days_to_payment=ROUND(
        AVG(
            payment.CALCULATE(
                days_to_pay=DATEDIFF("days", sale_date, payment_date)
            ).days_to_pay
        ),
        2
    )
)

gpm_2023 = Dealership.CALCULATE(
    total_revenue_2023=SUM(Sales.WHERE(YEAR(sale_date) == 2023).sale_price),
    total_cost_2023=SUM(Sales.WHERE(YEAR(sale_date) == 2023).car.cost)
).CALCULATE(
    gpm=(total_revenue_2023 - total_cost_2023) / total_cost_2023 * 100.0
)

highest_priced_car = Sales.WHERE(
    HAS(car.inventory_snapshots.WHERE((snapshot_date == sale_date) & (is_in_inventory == False))) == 1
).TOP_K(
    1, by=sale_price.DESC()
).CALCULATE(
    make=car.make,
    model=car.model,
    sale_price=sale_price
)

result = Customers.WHERE(
