result = Dealership.CALCULATE(
    num_weekend_payments_to_utility = COUNT(
        PaymentsMade.WHERE(
            (LOWER(vendor_name) == LOWER('Utility Company')) &
            (ISIN(DAYOFWEEK(payment_date), (1, 7)))
