inventory_cars = InventorySnapshots.WHERE(
    (YEAR(snapshot_date) == 2023) & (MONTH(snapshot_date) == 3)
).WHERE(
    RANKING(by=snapshot_date.DESC(), allow_ties=True) == 1
).WHERE(
    is_in_inventory == True
).car.CALCULATE(
    _id,
    make,
    model,
    year
)

result = Drugs.CALCULATE(
    drug_name=drug_name,
    avg_ddd=AVG(
        treatments_used_in.WHERE(
            PRESENT(end_dt)
        ).CALCULATE(
            ddd=tot_drug_amt / DATEDIFF("days", start_dt, end_dt)
        ).ddd
    )
)

ddd_calculation = DermTreatment.Drugs.CALCULATE(
    drug_name=drug_name,
    average_ddd=AVG(
        treatments_used_in.WHERE(
            PRESENT(end_dt)
        ).CALCULATE(
            treatment_duration=DATEDIFF("days", start_dt, end_dt)
        ).WHERE(
            treatment_duration > 0
        ).CALCULATE(
            ddd=tot_drug_amt / treatment_duration
        ).ddd
    )
)

