        )
    )
)

result = Treatments.WHERE(
    HAS(adverse_events) == 1
).adverse_events.WHERE(
    DATEDIFF("days", treatment.start_dt, reported_dt) <= 10
).CALCULATE(
    treatment_id=treatment.treatment_id,
    treatment_start_date=treatment.start_dt,
    adverse_event_date=reported_dt,
    adverse_event_description=description
)

result = Treatments.WHERE(
    is_placebo == True
).WHERE(
    HAS(concomitant_meds.WHERE(
        DATEDIFF("days", start_dt, concomitant_meds.start_dt) <= 14
    )) == 1
).concomitant_meds.CALCULATE(
    treatment_id=treatment.treatment_id,
    treatment_start_dt=treatment.start_dt,
    treatment_end_dt=treatment.end_dt,
    concomitant_med_start_dt=start_dt,
    concomitant_med_end_dt=end_dt
)

result = Patients.WHERE(
    (LOWER(gender) == 'male') & 
    (LOWER(ins_type) == 'private')
).CALCULATE(
    age_in_years = DATEDIFF("years", date_of_birth, DATETIME('now'))
).CALCULATE(
    average_age = AVG(age_in_years)
)

# First, create a collection of male patients with private insurance and calculate their current age in years.
male_private_patients_with_age = DermTreatment.Patients.WHERE(
    (LOWER(gender) == 'male') & (LOWER(ins_type) == 'private')
).CALCULATE(
    age=DATEDIFF("years", date_of_birth, 'now')
)

# Next, calculate the average of the ages from the collection above and round it to the nearest integer.
result = DermTreatment.CALCULATE(
    avg_patient_age=ROUND(AVG(male_private_patients_with_age.age), 0)
)

weekly_notification_summary = Ewallet.CALCULATE(
    start_of_current_week=DATETIME('now', 'start of week'),
    start_of_analysis_period=DATETIME('now', 'start of week', '-3 weeks')
).Users.WHERE(
    ISIN(country, ('US', 'Canada'))
).notifications.WHERE(
    (created_at >= start_of_analysis_period) & (created_at < start_of_current_week)
).CALCULATE(
    notification_week_start=DATETIME(created_at, 'start of week'),
    is_weekend_notification=ISIN(DAYNAME(created_at), ('Saturday', 'Sunday'))
).PARTITION(
    name='weekly_groups', by=(notification_week_start)
).CALCULATE(
    week=notification_week_start,
    total_notifications=COUNT(Notifications),
    weekend_notifications=SUM(is_weekend_notification)
)

result = Users.WHERE(LOWER(country) == LOWER('US')).transactions_sent.WHERE(
    DATEDIFF("days", created_at, 'now') <= 6
).CALCULATE(
    num_transactions=COUNT(Transactions),
    total_amount=SUM(amount)
).SINGULAR()

result = Users.CALCULATE(
    user_id=uid,
    marketing_opt_in=setting_snapshots.WHERE(
        RANKING(by=snapshot_date.DESC(), per="Users") == 1
    ).SINGULAR().marketing_opt_in
)

result = Users.CALCULATE(
    user_id=uid,
    total_duration=SUM(
        sessions.WHERE(
            (session_start_ts >= "2023-06-01") & 
            (session_start_ts < "2023-06-08")
        ).CALCULATE(
            duration_seconds=DATEDIFF("seconds", session_start_ts, session_end_ts)
        ).duration_seconds
    )
).WHERE(
    HAS(sessions.WHERE(
        (session_start_ts >= "2023-06-01") & 
        (session_start_ts < "2023-06-08")
    )) == 1
).ORDER_BY(total_duration.DESC())

user_session_durations = UserSessions.WHERE(
    (session_start_ts >= '2023-06-01') & (session_start_ts < '2023-06-08')
).CALCULATE(
    user_id=user_id,
    session_duration=DATEDIFF("seconds", session_start_ts, session_end_ts)
).PARTITION(
    name="sessions_by_user", by=(user_id,)
).CALCULATE(
    user_id=user_id,
    total_duration=SUM(UserSessions.session_duration)
).ORDER_BY(total_duration.DESC())

result = Ewallet.CALCULATE(
    total_count=COUNT(UserSessions.WHERE(
        DATEDIFF("days", session_start_ts, DATETIME('now')) <= 30
    ))
)

tuc_result = Ewallet.CALCULATE(
    tuc_count=COUNT(UserSessions.WHERE(session_start_ts >= DATETIME('now', '-1 month')))
)

