result = Merchants.WHERE(
    HAS(transactions_received.WHERE(
        (receiver_type == 1) & 
        (DATEDIFF("days", created_at, DATETIME("now")) <= 150)
    )) == 1
).CALCULATE(
    merchant_name=name,
    total_transactions=COUNT(transactions_received.WHERE(
        (receiver_type == 1) & 
        (DATEDIFF("days", created_at, DATETIME("now")) <= 150)
    )),
    total_amount=SUM(transactions_received.WHERE(
        (receiver_type == 1) & 
        (DATEDIFF("days", created_at, DATETIME("now")) <= 150)
    ).amount)
).TOP_K(2, by=total_amount.DESC())

# Get today's median balance for active retail merchants
result = Ewallet.CALCULATE(
    median_balance=MEDIAN(
        Merchants.WHERE(
            (LOWER(status) == LOWER('active')) & 
            (CONTAINS(LOWER(category), LOWER('retail')))
        ).balances.WHERE(
            DATEDIFF("days", updated_at, DATETIME('now')) == 0
        ).balance
    )
)

result = Ewallet.CALCULATE(
    median_merchant_balance=MEDIAN(
        Ewallet.MerchantBalances.WHERE(
            (DATETIME(updated_at, 'start of day') == DATETIME('now', 'start of day')) &
            (LOWER(merchant.status) == 'active') &
            CONTAINS(LOWER(merchant.category), 'retail')
        ).balance
    )
)

# First, find the earliest snapshot date in 2023
earliest_date_2023 = UserSettingSnapshots.WHERE(
    YEAR(snapshot_date) == 2023
).CALCULATE(
    min_date=MIN(UserSettingSnapshots.snapshot_date)
).SINGULAR().min_date

# Then calculate the averages for that specific date
result = Ewallet.CALCULATE(
    avg_daily_limit=AVG(
        UserSettingSnapshots.WHERE(
            snapshot_date == earliest_date_2023
        ).tx_limit_daily
    ),
    avg_monthly_limit=AVG(
        UserSettingSnapshots.WHERE(
            snapshot_date == earliest_date_2023
        ).tx_limit_monthly
    )
)

earliest_snapshots_in_2023 = Ewallet.UserSettingSnapshots.WHERE(YEAR(snapshot_date) == 2023)
earliest_date_in_2023 = Ewallet.CALCULATE(
    min_date=MIN(earliest_snapshots_in_2023.snapshot_date)
)
result = earliest_date_in_2023.CALCULATE(
    avg_tx_limit_daily=AVG(
        earliest_snapshots_in_2023.WHERE(snapshot_date == min_date).tx_limit_daily
    ),
    avg_tx_limit_monthly=AVG(
        earliest_snapshots_in_2023.WHERE(snapshot_date == min_date).tx_limit_monthly
    ),
)

average_session_duration_by_device = UserSessions.PARTITION(
    name="sessions_by_device", by=(device_type)
).CALCULATE(
    device_type=device_type,
    average_duration_seconds=AVG(
        UserSessions.CALCULATE(
            duration=DATEDIFF("seconds", session_start_ts, session_end_ts)
        ).duration
    )
)

result = Users.WHERE(
    HASNOT(notifications.WHERE(
        (created_at >= Users.created_at) & 
        (created_at <= DATETIME(Users.created_at, '+1 year'))
    )) == 1
).CALCULATE(
    username=username,
    email=email,
    signup_date=created_at
)

users_without_notifications_in_first_year = Ewallet.Users.WHERE(
    HASNOT(
        notifications.WHERE(created_at < DATETIME(created_at, '+1 year'))
    ) == 1
).CALCULATE(
    username=username,
    email=email,
    signup_date=created_at
)
